def run(intent, city_query, geo_status, geo_json, forecast_status, forecast_json):
    problems = []
    ok = True
    if intent not in ('city_outlook', 'rain_check'):
        return {'ok': True, 'problems': []}
    if not city_query:
        ok = False
        problems.append('missing city')
    if geo_status != 200 or not isinstance(geo_json, dict) or not (geo_json.get('results') or []):
        ok = False
        problems.append('could not resolve city')
    if forecast_status != 200 or not isinstance(forecast_json, dict):
        ok = False
        problems.append('could not fetch forecast')
    daily = (forecast_json or {}).get('daily') if isinstance(forecast_json, dict) else None
    if intent in ('city_outlook', 'rain_check') and ok and not daily:
        ok = False
        problems.append('forecast missing daily data')
    return {'ok': ok, 'problems': problems}

def run(intent, ok, problems, city, extract, forecast_json, question):
    if intent not in ('city_outlook', 'rain_check'):
        return {'score': 0, 'verdict': 'out_of_scope', 'reasons': ['Request is not weather-related.'], 'highlights': [], 'city': city, 'temps': [], 'precip': [], 'current': {}, 'escalate': False, 'rain_verdict': ''}
    if not ok:
        return {'score': 0, 'verdict': 'missing_data', 'reasons': problems or ['Weather data unavailable.'], 'highlights': [], 'city': city, 'temps': [], 'precip': [], 'current': {}, 'escalate': False, 'rain_verdict': ''}
    daily = forecast_json.get('daily') or {}
    current = forecast_json.get('current') or {}
    temps = []
    precip = []
    times = daily.get('time') or []
    tmax = daily.get('temperature_2m_max') or []
    tmin = daily.get('temperature_2m_min') or []
    pmax = daily.get('precipitation_probability_max') or []
    for i in range(min(len(times), 3)):
        temps.append({'date': times[i], 'high': tmax[i] if i < len(tmax) else None, 'low': tmin[i] if i < len(tmin) else None})
        precip.append(pmax[i] if i < len(pmax) else None)
    score = 0
    reasons = []
    if temps:
        score += 1
        reasons.append('Daily forecast available.')
    if current:
        score += 1
        reasons.append('Current conditions available.')
    rain_verdict = ''
    if intent == 'rain_check':
        p0 = precip[0] if precip else None
        if p0 is None:
            rain_verdict = 'unclear'
        elif p0 >= 50:
            rain_verdict = 'yes'
        elif p0 <= 20:
            rain_verdict = 'unlikely'
        else:
            rain_verdict = 'possible'
    return {'score': score, 'verdict': 'weather_ready', 'reasons': reasons, 'highlights': temps, 'city': city, 'temps': temps, 'precip': precip, 'current': current, 'escalate': False, 'rain_verdict': rain_verdict}

def run(intent, ok, problems, judge, city, question):
    if intent not in ('city_outlook', 'rain_check'):
        speech = 'I can help with weather questions only. Please ask about a city forecast, rain chance, or weather outlook.'
        report = '# Weather Assistant\n\n**Status:** Out of scope\n\nI only answer weather-related requests.'
        return {'speech': speech, 'report': report}
    if not ok:
        problem_text = '; '.join(problems or ['weather data unavailable'])
        speech = f'I could not give a weather verdict for {city or "that city"} because {problem_text}.'
        report = f'# Weather outlook for {city or "unknown location"}\n\n**Status:** Missing data\n\nProblems: {problem_text}'
        return {'speech': speech, 'report': report}
    current = judge.get('current') or {}
    temps = judge.get('temps') or []
    precip = judge.get('precip') or []
    parts = []
    for item in temps[:3]:
        if item and item.get('date'):
            hi = item.get('high')
            lo = item.get('low')
            parts.append(f"{item['date']}: {lo} to {hi}°")
    p0 = precip[0] if precip else None
    if intent == 'rain_check':
        if judge.get('rain_verdict') == 'yes':
            rain_line = f"Yes — rain is likely in {city} tomorrow, with about {p0}% chance."
        elif judge.get('rain_verdict') == 'unlikely':
            rain_line = f"No — rain looks unlikely in {city} tomorrow, with about {p0}% chance."
        elif judge.get('rain_verdict') == 'possible':
            rain_line = f"Rain is possible in {city} tomorrow, with about {p0}% chance."
        else:
            rain_line = f"I can't say clearly whether it will rain in {city} tomorrow because the rain chance is missing."
        temp_now = current.get('temperature_2m')
        speech = rain_line
        if temp_now is not None:
            speech += f" Current temperature is about {temp_now}°."
        report = f"# Weather outlook for {city}\n\n**Verdict:** {judge.get('rain_verdict') or 'unclear'}\n\n## Rain check\n- Tomorrow rain chance: {p0 if p0 is not None else 'n/a'}%\n\n## Current\n- Temperature: {temp_now if temp_now is not None else 'n/a'}\n\n## Outlook\n" + '\n'.join([f"- {p}" for p in parts])
        return {'speech': speech[:900], 'report': report}
    ptxt = ''
    if precip:
        ptxt = f"Rain chances: {', '.join(str(x) for x in precip[:3] if x is not None)}%."
    temp_now = current.get('temperature_2m')
    speech = f"The weather outlook for {city} is ready. Right now it is about {temp_now}° if current data is available, and the next days are: {' '.join(parts)} {ptxt}".strip()
    report = f"# Weather outlook for {city}\n\n**Verdict:** Weather ready\n\n## Current\n- Temperature: {temp_now if temp_now is not None else 'n/a'}\n\n## Outlook\n" + '\n'.join([f"- {p}" for p in parts])
    if ptxt:
        report += f"\n- {ptxt}"
    return {'speech': speech[:900], 'report': report}
